NEO4J.ActorWithMovies.loadAll.where:
MATCH (n:Actor)
WHERE (n.name = $name) AND EXISTS { MATCH (n)-[:ACTED_IN]->(:Movie) }
RETURN {root: {props: properties(n), labels: labels(n)}, rels: {movies: [(n)-[r1:ACTED_IN]->(t1:Movie) | {props: properties(t1), labels: labels(t1)}]}} AS result

NEO4J.ActorWithMovies.count:
MATCH (n:Actor)
WHERE EXISTS { MATCH (n)-[:ACTED_IN]->(:Movie) }
RETURN count(n) AS count

NEO4J.ActorWithLatestMovie.loadAll:
