FALKORDB.PersonCareer.loadAll:
MATCH (n:Person)
CALL { WITH n OPTIONAL MATCH (n)-[r1:WORKS_FOR]->(t1:Organization) RETURN collect(CASE WHEN t1 IS NOT NULL THEN {rel: properties(r1), target: {props: properties(t1), labels: labels(t1)}} END) AS v1 }
RETURN {root: {props: properties(n), labels: labels(n)}, rels: {employmentHistory: v1}} AS result

FALKORDB.ActorStats.loadAll:
MATCH (n:Actor)
CALL { WITH n OPTIONAL MATCH (n)-[:ACTED_IN]->()-[:DIRECTED_BY]->(t1) WHERE t1:Director RETURN collect(DISTINCT CASE WHEN t1 IS NOT NULL THEN {props: properties(t1), labels: labels(t1)} END) AS v1 }
CALL { WITH n OPTIONAL MATCH (n)-[:ACTED_IN]->(h2)-[:DIRECTED_BY]->(t2) WHERE t2:Director WITH n, t2, h2 ORDER BY h2.released IS NULL, h2.released ASC RETURN head(collect(DISTINCT CASE WHEN t2 IS NOT NULL THEN {props: properties(t2), labels: labels(t2)} END)) AS v2 }
CALL { WITH n OPTIONAL MATCH (n)-[:ACTED_IN]->(t3) RETURN count(t3) AS v3 }
CALL { WITH n OPTIONAL MATCH (n)-[:RATED]->(t4) RETURN avg(t4.score) AS v4 }
CALL { WITH n OPTIONAL MATCH (n)-[:RATED]->(t5) RETURN max(t5.score) AS v5 }
RETURN {root: {props: properties(n), labels: labels(n)}, rels: {directors: v1, firstDirector: v2, movieCount: v3, averageRating: v4, bestRating: v5}} AS result
